# Log actions that move a document; used to work out where it stood before
# the old scan froze it.
IN_TRANSIT_AFTER = {'released', 'return_initiated'}
RETURNED_AFTER = {'return_received', 'citizen_return_initiated'}
HELD_AFTER = {'created', 'received', 'corrected'}


def undo_automatic_missing(apps, schema_editor):
    """
    The old 48h scan set a late document's status to 'missing' (with a
    staff-less 'flagged_missing' log), which froze it. Being late is now
    "Overdue" and leaves the status alone: such documents get back the
    status they had, their automatic log entries become 'flagged_overdue',
    and their alerts stay as Overdue alerts (the field's default). A missing
    report made by a staff member stays Missing, remembering its prior status.
    """
    Document = apps.get_model('documents', 'Document')
    DocumentLog = apps.get_model('documents', 'DocumentLog')
    for document in Document.objects.filter(status='missing'):
        logs = list(DocumentLog.objects.filter(document=document).order_by('timestamp', 'id'))
        flags = [l for l in logs if l.action == 'flagged_missing']
        if not flags:
            continue
        last_flag = flags[-1]
        before = 'in_progress'
        for log in logs:
            if log.pk == last_flag.pk:
                break
            if log.action in IN_TRANSIT_AFTER:
                before = 'in_transit'
            elif log.action in RETURNED_AFTER:
                before = 'returned'
            elif log.action in HELD_AFTER:
                before = 'in_progress'
        if last_flag.acted_by_id is None:
            Document.objects.filter(pk=document.pk).update(status=before)
        else:
            Document.objects.filter(pk=document.pk).update(status_before_missing=before)
    DocumentLog.objects.filter(action='flagged_missing', acted_by__isnull=True).update(action='flagged_overdue')


def redo_automatic_missing(apps, schema_editor):
    DocumentLog = apps.get_model('documents', 'DocumentLog')
    DocumentLog.objects.filter(action='flagged_overdue').update(action='flagged_missing')


